import datetime
import jsonpickle
from IQEngine.core.events import Event, EventEnum
from IQEngine.const import AccountType, RunType
from IQCommon.logger import system_log, strategy_log
class Executor(object):
    __doc__ = '\n    执行器，驱动事件主循环\n    '
    def __init__(self, engine):
        self._engine = engine
        self._last_before_trading = None
        self._create_event()
    def _create_event(self):
        self.PRE_BEFORE_TRADING_START = Event(EventEnum.PRE_BEFORE_TRADING_START)
        self.POST_BEFORE_TRADING_START = Event(EventEnum.POST_BEFORE_TRADING_START)
        self.PRE_HANDLE_AUCTION = Event(EventEnum.PRE_HANDLE_AUCTION)
        self.POST_HANDLE_AUCTION = Event(EventEnum.POST_HANDLE_AUCTION)
        self.PRE_HANDLE_DATA = Event(EventEnum.PRE_HANDLE_DATA)
        self.POST_HANDLE_DATA = Event(EventEnum.POST_HANDLE_DATA)
        self.PRE_HANDLE_TICK = Event(EventEnum.PRE_HANDLE_TICK)
        self.POST_HANDLE_TICK = Event(EventEnum.POST_HANDLE_TICK)
        self.PRE_AFTER_TRADING_END = Event(EventEnum.PRE_AFTER_TRADING_END)
        self.POST_AFTER_TRADING_END = Event(EventEnum.POST_AFTER_TRADING_END)
        self.PRE_SETTLEMENT = Event(EventEnum.PRE_SETTLEMENT)
        self.POST_SETTLEMENT = Event(EventEnum.POST_SETTLEMENT)
        self.SETTLEMENT = Event(EventEnum.SETTLEMENT)
    def save(self, state):
        return None
    def load(self):
        return None
    def run(self, bar_dict):
        start_date = self._engine.config.strategy.start_date
        end_date = self._engine.config.strategy.end_date
        frequency = self._engine.config.strategy.frequency
        event_bus = self._engine.event_bus
        self.PRE_HANDLE_AUCTION.bar_dict = bar_dict
        self.POST_HANDLE_AUCTION.bar_dict = bar_dict
        self.PRE_HANDLE_DATA.bar_dict = bar_dict
        self.POST_HANDLE_DATA.bar_dict = bar_dict
        for event in self._engine.event_source.events(start_date, end_date, frequency):
            if (event.event_type == EventEnum.HANDLE_TICK):
                self.check_before_trading(event)
                self.update_time(event)
                bar_dict.update_dt(event.calendar_dt)
                event_bus.publish_event(self.PRE_HANDLE_TICK)
                event_bus.publish_event(event)
                event_bus.publish_event(self.POST_HANDLE_TICK)
                continue
            elif (event.event_type == EventEnum.HANDLE_AUCTION):
                self.check_before_trading(event)
                self.update_time(event)
                bar_dict.update_dt(event.calendar_dt)
                event_bus.publish_event(self.PRE_HANDLE_AUCTION)
                event.bar_dict = bar_dict
                event_bus.publish_event(event)
                event_bus.publish_event(self.POST_HANDLE_AUCTION)
                continue
            elif (event.event_type == EventEnum.HANDLE_DATA):
                event.bar_dict = bar_dict
                self.check_before_trading(event)
                self.update_time(event)
                bar_dict.update_dt(event.calendar_dt)
                event_bus.publish_event(self.PRE_HANDLE_DATA)
                event_bus.publish_event(event)
                event_bus.publish_event(self.POST_HANDLE_DATA)
                if (self._engine.config.strategy.run_type == RunType.TRADING):
                    self.publish_settlement()
                continue
            elif (event.event_type == EventEnum.BEFORE_TRADING_START):
                event.bar_dict = bar_dict
                self.check_before_trading(event)
                continue
            elif (event.event_type == EventEnum.AFTER_TRADING_END):
                self.update_time(event)
                event.bar_dict = bar_dict
                event_bus.publish_event(self.PRE_AFTER_TRADING_END)
                event_bus.publish_event(event)
                event_bus.publish_event(self.POST_AFTER_TRADING_END)
                if (self._engine.config.strategy.run_type == RunType.TRADING):
                    self.publish_settlement()
                continue
            else:
                self.update_time(event)
                event_bus.publish_event(event)
                continue
        else:
            self.publish_settlement()
    def update_time(self, event):
        self._engine.calendar_dt = event.calendar_dt
        self._engine.trading_dt = event.trading_dt
    def publish_settlement(self):
        self._engine.event_bus.publish_event(self.PRE_SETTLEMENT)
        self._engine.event_bus.publish_event(self.SETTLEMENT)
        self._engine.event_bus.publish_event(self.POST_SETTLEMENT)
    def check_before_trading(self, event):
        if (self._last_before_trading == event.trading_dt.date()):
            return False
        elif isinstance(self._last_before_trading, datetime.datetime):
            if (event.trading_dt.hour <= 18):
                return False
            elif (self._last_before_trading.day == event.trading_dt.day):
                return False
            elif self._engine.config.other.is_hold:
                return False
            elif self._last_before_trading:
                self.publish_settlement()
        if (AccountType.FUTURE.value in self._engine.config.strategy.accounts):
            if (event.trading_dt.hour > 18):
                self._last_before_trading = event.trading_dt
            else:
                self._last_before_trading = event.trading_dt.date()
        else:
            self._last_before_trading = event.trading_dt.date()
        self.update_time(event)
        if (self._engine.config.strategy.run_type == RunType.BACKTEST):
            self._engine.event_bus.publish_event(self.PRE_BEFORE_TRADING_START)
        if (self._engine.config.strategy.run_type == RunType.TRADING):
            try:
                server_restart_do_before_type = str(self._engine.config.user.server_restart_not_do_before)
            except AttributeError: server_restart_do_before_type = '0'
            now_date = datetime.date.today()
            flag = False
            if (server_restart_do_before_type == '0'):
                flag = True
            else:
                broker_persist = jsonpickle.decode(self._engine.persist_helper._persist_provider.get_data('broker'))
                if (broker_persist is not None):
                    on_before_trading_start_time_info = broker_persist.get('on_before_trading_start_time')
                    if (on_before_trading_start_time_info is not None):
                        today_date = now_date.strftime('%Y-%m-%d')
                        if (today_date in on_before_trading_start_time_info):
                            today_info = on_before_trading_start_time_info[today_date]
                            if (len(today_info) == 0):
                                flag = True
                        else:
                            flag = True
            if flag:
                self._engine.event_bus.publish_event(Event(EventEnum.BEFORE_TRADING_START, calendar_dt=event.calendar_dt, trading_dt=event.trading_dt, bar_dict=event.bar_dict))
        else:
            self._engine.event_bus.publish_event(Event(EventEnum.BEFORE_TRADING_START, calendar_dt=event.calendar_dt, trading_dt=event.trading_dt, bar_dict=event.bar_dict))
        self._engine.event_bus.publish_event(self.POST_BEFORE_TRADING_START)
        return True
